//! Fixed folding of real typed source owners, after their Common IO child.
use super::*;
use super::state_columns::OriginalStateColumnsDataV1;
use super::sources::ActualNormalStateSourcesV1;
use std::cell::RefCell;
use oasis7_formal_protocol::{incremental_execution::{ExecutionTransaction,ExecutionFence},incremental_state::MerkleNodeReader};
fn overlay(error:oasis7_world_state::incremental_field_overlay::WorldFieldOverlayErrorV1)->BodyMutationError{match error{oasis7_world_state::incremental_field_overlay::WorldFieldOverlayErrorV1::Execution(error)=>BodyMutationError::Execution(error),oasis7_world_state::incremental_field_overlay::WorldFieldOverlayErrorV1::Value(error)=>BodyMutationError::Value(error),other=>paid(other)}}
pub(super) fn fold_actual_normal_state_sources_v1<M:MerkleNodeReader>(before:&OriginalStateColumnsDataV1,source:&ActualNormalStateSourcesV1,tx:&ExecutionTransaction<'_,M>,common:&mut FormalBoundedContextV1<'_>,live:&ExecutionFence)->Result<OriginalStateColumnsDataV1,BodyMutationError>{
 source.marketplace.validate(tx,common.memory(),live)?;source.reward.validate(tx,common.memory(),live)?;source.diplomacy.validate(tx,common.memory(),live)?;source.governance.validate(tx,common.memory(),live)?;source.controls.validate(tx,common.memory(),live)?;source.main_policy.validate(tx,common.memory(),live)?;source.materials.validate(tx,common.memory(),live)?;source.fixed.validate(tx,common.memory(),live)?;source.native.validate(tx,common.memory(),live).map_err(overlay)?;source.primitive.validate(tx,common.memory(),live).map_err(overlay)?;source.inventory.validate(tx,common.memory(),live).map_err(overlay)?;source.industry.validate(tx,common.memory(),live).map_err(overlay)?;source.agent_authority.validate(tx,common.memory(),live)?;source.factory_authority.validate(tx,common.memory(),live)?;source.agents.validate(tx,common.memory(),live).map_err(overlay)?;source.module_states.validate(tx,common.memory(),live)?;
 let mut out=before.fork_data_v1(common)?;let shared=RefCell::new(common);
 source.controls.visit_groups_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,before,after,is_set|{if !before&&after{let mut common=shared.borrow_mut();let groups=out.map_data_v1(field,&mut common)?.ok_or_else(||invalid("Control original groups missing"))?;let groups=super::nested_rows::with_original_group_presence_data_v1(groups,semantic,key,before,after,is_set,&mut common)?;out.replace_original_map_data_v1(field,groups,&mut common)?}Ok::<_,BodyMutationError>(())})?;
 source.controls.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value,is_set|{let mut common=shared.borrow_mut();if field=="product_validation_delivery_cursor"{out.apply_original_patch_data_v1(field,semantic,key,value,&mut common)}else{let groups=out.map_data_v1(field,&mut common)?.ok_or_else(||invalid("Control original groups missing"))?;let groups=super::nested_rows::with_original_nested_member_data_v1(groups,semantic,key,value,is_set,false,&mut common)?;out.replace_original_map_data_v1(field,groups,&mut common)}})?;
 source.controls.visit_groups_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,before,after,is_set|{if before&&!after{let mut common=shared.borrow_mut();let groups=out.map_data_v1(field,&mut common)?.ok_or_else(||invalid("Control original groups missing"))?;let groups=super::nested_rows::with_original_group_presence_data_v1(groups,semantic,key,before,after,is_set,&mut common)?;out.replace_original_map_data_v1(field,groups,&mut common)?}Ok::<_,BodyMutationError>(())})?;
 source.main_policy.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value|out.apply_original_patch_data_v1(field,semantic,key,value,&mut shared.borrow_mut()))?;
 source.materials.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value|out.apply_original_patch_data_v1(field,semantic,key,value,&mut shared.borrow_mut()))?;
 source.fixed.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value|out.apply_original_patch_data_v1(field,semantic,key,value,&mut shared.borrow_mut()))?;
 source.native.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value|out.apply_original_patch_data_v1(field,semantic,key,value,&mut shared.borrow_mut()))?;
 source.primitive.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value|out.apply_original_patch_data_v1(field,semantic,key,value,&mut shared.borrow_mut()))?;
 source.industry.visit_with_work_v1(&mut|bytes|shared.borrow_mut().charge(1,bytes as u64).map_err(paid),|path,semantic,key,value|{if path.len()!=1{return Err(invalid("Industry original State path"))}out.apply_original_patch_data_v1(path[0],semantic,key,value,&mut shared.borrow_mut())})?;
 source.agent_authority.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value|out.apply_original_patch_data_v1(field,semantic,key,value,&mut shared.borrow_mut()))?;
 source.factory_authority.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value|out.apply_original_patch_data_v1(field,semantic,key,value,&mut shared.borrow_mut()))?;
 source.agents.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value|out.apply_original_patch_data_v1(field,semantic,key,value,&mut shared.borrow_mut()))?;
 source.module_states.visit_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|field,semantic,key,value|out.apply_original_patch_data_v1(field,semantic,key,value,&mut shared.borrow_mut()))?;
 // True empty-group presence is independent of its member count. Add groups
 // before members and remove them after members; no missing-group shortcut.
 source.inventory.visit_groups_with_work_v1(&mut|bytes|shared.borrow_mut().charge(1,bytes as u64).map_err(paid),|_ledger,semantic,key,before,after|{if !before&&after{let mut common=shared.borrow_mut();let rows=out.map_data_v1("material_ledgers",&mut common)?.ok_or_else(||invalid("actual Ledger groups missing"))?;let rows=super::nested_rows::with_original_group_presence_data_v1(rows,semantic,key,before,after,false,&mut common)?;out.replace_original_map_data_v1("material_ledgers",rows,&mut common)?}Ok::<_,BodyMutationError>(())})?;
 source.inventory.visit_with_work_v1(&mut|bytes|shared.borrow_mut().charge(1,bytes as u64).map_err(paid),|path,semantic,key,value|{if path.len()!=1{return Err(invalid("Inventory original State path"))}let mut common=shared.borrow_mut();if path[0]=="material_ledgers"{let groups=out.map_data_v1("material_ledgers",&mut common)?.ok_or_else(||invalid("actual Ledger groups missing"))?;let rows=super::nested_rows::with_original_nested_member_data_v1(groups,semantic,key,value,false,false,&mut common)?;out.replace_original_map_data_v1("material_ledgers",rows,&mut common)}else{out.apply_original_patch_data_v1(&path[0],semantic,key,value,&mut common)}})?;
 source.inventory.visit_groups_with_work_v1(&mut|bytes|shared.borrow_mut().charge(1,bytes as u64).map_err(paid),|_ledger,semantic,key,before,after|{if before&&!after{let mut common=shared.borrow_mut();let rows=out.map_data_v1("material_ledgers",&mut common)?.ok_or_else(||invalid("actual Ledger groups missing"))?;let rows=super::nested_rows::with_original_group_presence_data_v1(rows,semantic,key,before,after,false,&mut common)?;out.replace_original_map_data_v1("material_ledgers",rows,&mut common)?}Ok::<_,BodyMutationError>(())})?;
 let common=shared.into_inner();super::market_fold::fold_market_v1(&mut out,&source.marketplace,tx,common,live)?;super::reward_fold::fold_reward_v1(&mut out,&source.reward,tx,common,live)?;super::diplomacy_fold::fold_diplomacy_v1(&mut out,&source.diplomacy,tx,common,live)?;super::governance_fold::fold_governance_v1(&mut out,&source.governance,tx,common,live)?;source.reward.validate(tx,common.memory(),live)?;source.diplomacy.validate(tx,common.memory(),live)?;source.governance.validate(tx,common.memory(),live)?;source.controls.validate(tx,common.memory(),live)?;source.main_policy.validate(tx,common.memory(),live)?;source.materials.validate(tx,common.memory(),live)?;source.fixed.validate(tx,common.memory(),live)?;source.native.validate(tx,common.memory(),live).map_err(overlay)?;source.primitive.validate(tx,common.memory(),live).map_err(overlay)?;source.inventory.validate(tx,common.memory(),live).map_err(overlay)?;source.industry.validate(tx,common.memory(),live).map_err(overlay)?;source.agent_authority.validate(tx,common.memory(),live)?;source.factory_authority.validate(tx,common.memory(),live)?;source.agents.validate(tx,common.memory(),live).map_err(overlay)?;source.module_states.validate(tx,common.memory(),live)?;Ok(out)
}
